package thaumcraft.verification;

import java.util.*;
import java.util.function.BiConsumer;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.common.util.FakePlayerFactory;
import thaumcraft.api.aspects.*;
import thaumcraft.api.visnet.VisNetHandler;
import thaumcraft.items.*;
import thaumcraft.knowledge.KnowledgeService;
import thaumcraft.production.*;
import thaumcraft.registry.*;

final class AdvancedAlchemyVerification {
    private static final BlockPos POS=new BlockPos(1712,120,0);
    private static void build(ServerLevel l,BlockPos p){for(int part=0;part<18;part++){var q=p.offset(AdvancedAlchemyBlock.offset(part));l.getChunkAt(q);l.setBlockAndUpdate(q,part==13?Blocks.AIR.defaultBlockState():AdvancedAlchemyBlock.original(part));}}
    private static void ticks(AdvancedAlchemyBlockEntity f,int n){for(int i=0;i<n;i++)f.serverTick();}
    static void run(ServerLevel l,BiConsumer<Boolean,String> check){
        build(l,POS);var player=FakePlayerFactory.get(l,new GameProfile(UUID.fromString("66a5fe4a-0d76-4657-8754-f7c39262fbd4"),"TC4_AdvAlchemy"));player.getInventory().clearContent();player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.moveTo(POS.getCenter());KnowledgeService.initialize(player);var novice=FakePlayerFactory.get(l,new GameProfile(UUID.fromString("46a5fe4a-0d76-4657-8754-f7c39262fbd4"),"TC4_AdvNovice"));KnowledgeService.initialize(novice);
        var wand=new ItemStack(R3Equipment.WAND.get());wand.set(WandComponents.PARTS.get(),new thaumcraft.api.wands.WandParts("silverwood","gold"));for(var a:List.of(Aspects.FIRE,Aspects.WATER,Aspects.ORDER))WandVis.set(wand,a,10000);
        check.accept(!AdvancedAlchemyBlock.activate(novice,wand,POS.east())&&WandVis.get(wand,Aspects.FIRE)==10000,"unresearched furnace does not assemble or consume vis");KnowledgeService.mutate(player,k->k.completeResearch("ADVALCHEMYFURNACE"));
        l.setBlockAndUpdate(POS.offset(1,1,1),Blocks.STONE.defaultBlockState());check.accept(!AdvancedAlchemyBlock.activate(player,wand,POS.east())&&WandVis.get(wand,Aspects.FIRE)==10000,"incorrect upper alembic prevents formation without payment");l.setBlockAndUpdate(POS.offset(1,1,1),R3Content.ALEMBIC.get().defaultBlockState());
        WandVis.set(wand,Aspects.WATER,0);check.accept(!AdvancedAlchemyBlock.activate(player,wand,POS.east())&&WandVis.get(wand,Aspects.FIRE)==10000,"missing one primal leaves all other wand charges unchanged");WandVis.set(wand,Aspects.WATER,10000);
        l.setBlockAndUpdate(POS.above(),Blocks.GLASS.defaultBlockState());player.setItemInHand(InteractionHand.MAIN_HAND,wand);var result=wand.getItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(POS.east().getCenter(),Direction.UP,POS.east(),false)));
        check.accept(result.consumesAction()&&l.getBlockEntity(POS) instanceof AdvancedAlchemyBlockEntity,"ordinary wand interaction forms advanced furnace");for(var a:List.of(Aspects.FIRE,Aspects.WATER,Aspects.ORDER))check.accept(WandVis.get(wand,a)==5000,"formation spends exactly fifty discounted vis of "+a.getTag());
        for(int part=0;part<18;part++)if(part!=13){var q=POS.offset(AdvancedAlchemyBlock.offset(part));check.accept(l.getBlockState(q).is(R4Content.ADVANCED_FURNACE.get())&&l.getBlockState(q).getValue(AdvancedAlchemyBlock.PART)==part,"original structure position is recorded: "+part);}check.accept(l.getBlockState(POS.above()).is(Blocks.GLASS),"assembly leaves original unchecked upper-center cell untouched");
        var f=(AdvancedAlchemyBlockEntity)l.getBlockEntity(POS);ticks(f,5);check.accept(f.heat==-1&&f.powerAqua==0&&f.powerPerditio==0,"unpowered furnace cools every five ticks, including negative heat");check.accept(!f.process(new ItemStack(Items.COAL)),"unpowered furnace cannot smelt thrown items");
        var auraPos=POS.east(7);l.getChunkAt(auraPos);l.setBlockAndUpdate(auraPos,R2Content.AURA_NODE.get().defaultBlockState());var aura=(thaumcraft.blocks.AuraNodeBlockEntity)l.getBlockEntity(auraPos);aura.initialize(Map.of("ignis",2500,"aqua",2500,"perditio",2500),thaumcraft.api.nodes.NodeState.Type.NORMAL,thaumcraft.api.nodes.NodeState.Modifier.NONE);
        var sourcePos=POS.east(5);l.setBlockAndUpdate(sourcePos,R3Content.ENERGIZED_NODE.get().defaultBlockState());var source=(thaumcraft.visnet.EnergizedNodeBlockEntity)l.getBlockEntity(sourcePos);source.initialize(aura);VisNetHandler.addNode(l,source);ticks(f,5);check.accept(f.heat==48&&f.powerAqua==50&&f.powerPerditio==50,"native vis network supplies all three original power channels");
        f.heat=f.powerAqua=f.powerPerditio=500;l.getServer().getWorldData().overworldData().setGameTime(l.getGameTime()+1);ticks(f,5);check.accept(f.heat==549&&f.powerAqua==550&&f.powerPerditio==550,"original less-than-or-equal threshold allows one final fifty-vis charge above five hundred");l.setBlockAndUpdate(sourcePos,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(auraPos,Blocks.AIR.defaultBlockState());
        var coal=new ItemStack(Items.COAL,3);var values=thaumcraft.data.ThaumcraftData.aspects(l.getServer(),coal);int amount=values.values().stream().mapToInt(Integer::intValue).sum();check.accept(amount>0,"test input resolves actual loaded object aspects");f.heat=f.powerPerditio=f.powerAqua=500;var item=new ItemEntity(l,POS.getX()+.5,POS.getY()+.8,POS.getZ()+.5,coal);l.getBlockState(POS).entityInside(l,POS,item);
        check.accept(item.getItem().getCount()==2&&f.store.amount()==amount&&f.heat==500-amount*2&&f.powerPerditio==500-amount&&f.powerAqua==500-amount,"one thrown item consumes exact vis and fills its complete aspect list");check.accept(f.cooldown==(int)(5+Math.max(0,(1-f.heat/500f)*100)),"cooldown is calculated from heat after smelting");l.getBlockState(POS).entityInside(l,POS,item);check.accept(item.getItem().getCount()==2&&f.store.amount()==amount,"cooldown prevents a repeated collision from consuming another item");
        for(var entry:values.entrySet())check.accept(f.store.containerContains(Aspect.getAspect(entry.getKey()))==entry.getValue(),"furnace retains full actual aspect quantity: "+entry.getKey());
        for(var d:Direction.Plane.HORIZONTAL){var p=POS.relative(d);var n=l.getCapability(EssentiaCapabilities.TRANSPORT,p,d);check.accept(n!=null&&n.isConnectable(d)&&!n.isConnectable(d.getOpposite())&&!n.canInputFrom(d)&&n.getSuctionAmount(d)==0,"native nozzle capability exposes only outward extraction: "+d);check.accept(l.getCapability(EssentiaCapabilities.SOURCE,p,null)!=null,"nozzle exposes shared infusion source capability: "+d);check.accept(l.getBlockState(p).getAnalogOutputSignal(l,p)==1,"original comparator reports binary nonempty tank on "+d);}
        var n=(AdvancedAlchemyNozzleBlockEntity)l.getBlockEntity(POS.east());var first=f.store.first();int firstAmount=f.store.containerContains(first);check.accept(n.getEssentiaAmount(Direction.EAST)==firstAmount,"nozzle quantity is first aspect amount rather than mixed total");check.accept(n.takeEssentia(first,1,Direction.WEST)==0&&f.store.containerContains(first)==firstAmount,"inward extraction is refused without tank loss");check.accept(n.takeEssentia(first,1,Direction.EAST)==1&&f.store.containerContains(first)==firstAmount-1&&((AdvancedAlchemyNozzleBlockEntity)l.getBlockEntity(POS.west())).containerContains(first)==firstAmount-1,"all four nozzles immediately observe extraction from one shared tank");
        f.cooldown=0;f.store.setAspects(new AspectList().add(Aspects.FIRE,500));int heat=f.heat;check.accept(!f.process(coal)&&f.heat==heat&&f.store.amount()==500,"full tank refuses an item without spending power");f.store.clear();check.accept(n.getEssentiaType(Direction.EAST)==null&&n.getEssentiaAmount(Direction.EAST)==0&&l.getBlockState(POS.east()).getAnalogOutputSignal(l,POS.east())==0,"empty nozzle is safe and comparator becomes zero");
        f.store.setAspects(new AspectList().add(Aspects.FIRE,32));var pipePos=POS.east(2);l.getChunkAt(pipePos);l.setBlockAndUpdate(pipePos,R3Content.TUBE.get().defaultBlockState());l.setBlockAndUpdate(pipePos.below(),R3Content.WARDED_JAR.get().defaultBlockState());var pipe=(TransportBlockEntity)l.getBlockEntity(pipePos);var jar=(TransportBlockEntity)l.getBlockEntity(pipePos.below());jar.applyLabel(Aspects.FIRE);for(int i=0;i<1000;i++){pipe.serverTick();jar.serverTick();}check.accept(jar.store.containerContains(Aspects.FIRE)==32&&pipe.store.amount()==0&&f.store.amount()==0,"native pipe draws all essentia from advanced nozzle into a labelled jar without duplication");l.setBlockAndUpdate(pipePos,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(pipePos.below(),Blocks.AIR.defaultBlockState());
        check.accept(l.getBlockState(POS).getCollisionShape(l,POS,net.minecraft.world.phys.shapes.CollisionContext.of(item)).max(Direction.Axis.Y)==.7&&l.getBlockState(POS).getCollisionShape(l,POS,net.minecraft.world.phys.shapes.CollisionContext.of(player)).max(Direction.Axis.Y)==1,"furnace collision admits dropped items while retaining full living-entity collision");
        f.heat=500;f.powerAqua=0;f.powerPerditio=500;check.accept(!f.process(coal)&&f.heat==500,"missing aqua power prevents processing without spending heat");
        l.setBlockAndUpdate(POS.offset(1,1,1),Blocks.AIR.defaultBlockState());check.accept(f.destroy,"removing one upper component marks the controller for original next-tick dismantling");f.serverTick();for(int part=0;part<18;part++)if(part!=13&&part!=17)check.accept(l.getBlockState(POS.offset(AdvancedAlchemyBlock.offset(part))).is(AdvancedAlchemyBlock.original(part).getBlock()),"dismantling restores surviving original component: "+part);check.accept(l.getBlockState(POS.offset(1,1,1)).isAir()&&l.getBlockState(POS.above()).is(Blocks.GLASS),"dismantling leaves broken cell and unchecked upper center untouched");
        var orphan=POS.east(32);l.getChunkAt(orphan);l.setBlockAndUpdate(orphan.west(),Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(orphan,R4Content.ADVANCED_FURNACE.get().defaultBlockState().setValue(AdvancedAlchemyBlock.PART,5));l.getBlockState(orphan).tick(l,orphan,l.random);check.accept(l.getBlockState(orphan).is(R4Content.ADVANCED_CONSTRUCT.get()),"loaded orphan nozzle restores its original construct instead of remaining a broken shell");
        int chunkX=2400,chunkZ=2400;l.getChunk(chunkX,chunkZ);while(l.hasChunk(chunkX+1,chunkZ))chunkX++;var edge=new BlockPos(chunkX*16+15,120,chunkZ*16+8);l.setBlock(edge,R4Content.ADVANCED_FURNACE.get().defaultBlockState().setValue(AdvancedAlchemyBlock.PART,3),18);var edgeNozzle=(AdvancedAlchemyNozzleBlockEntity)l.getBlockEntity(edge);check.accept(!l.hasChunk(chunkX+1,chunkZ)&&edgeNozzle.furnace()==null&&edgeNozzle.getEssentiaType(Direction.WEST)==null&&!l.hasChunk(chunkX+1,chunkZ),"nozzle and orphan queries never load the adjacent controller chunk");l.getBlockState(edge).tick(l,edge,l.random);check.accept(l.getBlockState(edge).is(R4Content.ADVANCED_FURNACE.get())&&!l.hasChunk(chunkX+1,chunkZ),"orphan maintenance waits for unloaded controller rather than dismantling or force-loading");l.setBlock(edge,Blocks.AIR.defaultBlockState(),18);
        build(l,POS);for(var a:List.of(Aspects.FIRE,Aspects.WATER,Aspects.ORDER))WandVis.set(wand,a,10000);check.accept(AdvancedAlchemyBlock.activate(player,wand,POS.east()),"restored construction can be assembled again");f=(AdvancedAlchemyBlockEntity)l.getBlockEntity(POS);f.heat=371;f.powerPerditio=417;f.powerAqua=429;f.cooldown=37;f.store.setAspects(new AspectList().add(Aspects.FIRE,23).add(Aspects.WATER,11));f.sync();
        check.accept(l.getBlockState(POS).getValue(AdvancedAlchemyBlock.LIGHT)==8,"original heat determines native block light");check.accept(l.getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("thaumcraft:advanced_alchemical_construct")).isPresent()&&thaumcraft.data.ThaumcraftData.get(l.getServer()).research().containsKey("ADVALCHEMYFURNACE"),"original advanced-construct recipe and research are loaded");
    }
    static void reload(ServerLevel l,BiConsumer<Boolean,String> check){l.getChunkAt(POS);var f=(AdvancedAlchemyBlockEntity)l.getBlockEntity(POS);check.accept(f!=null&&f.heat==371&&f.powerPerditio==417&&f.powerAqua==429,"furnace persists each power channel through an actual restart");check.accept(f.store.amount()==34&&f.store.containerContains(Aspects.FIRE)==23&&f.store.containerContains(Aspects.WATER)==11,"mixed tank quantities survive actual world reload");check.accept(f.cooldown==0&&!f.destroy,"original transient processing and dismantling flags are reset on reload");for(var d:Direction.Plane.HORIZONTAL){var p=POS.relative(d);l.getChunkAt(p);var n=l.getCapability(EssentiaCapabilities.TRANSPORT,p,d);check.accept(n!=null&&n.takeEssentia(Aspects.FIRE,1,d)==1,"reloaded nozzle reconnects to persisted shared tank: "+d);}check.accept(f.store.containerContains(Aspects.FIRE)==19,"all reloaded nozzle extractions affect one tank");}
}
